['state']??'Manipur'))?>"></div><div class="fco-field"><label>Postal Code</label><input name="delivery_postal_code" value="<?=fcoEsc($old['delivery_postal_code']??($profile['postal_code']??''))?>"></div></div><div class="fco-grid"><div class="fco-field"><label>Latitude</label><input id="lat" name="customer_latitude" value="<?=fcoEsc($old['customer_latitude']??'')?>"></div><div class="fco-field"><label>Longitude</label><input id="lng" name="customer_longitude" value="<?=fcoEsc($old['customer_longitude']??'')?>"></div></div><button type="button" id="locate" style="border:0;background:#eaf7f2;color:#087d64;border-radius:9px;padding:8px 10px;font-size:9px;font-weight:900">⌖ Use current location</button></section><section class="fco-card"><h2>Order summary</h2><div class="fco-row"><span>Subtotal</span><b><?=fcoMoney($p['subtotal']??0)?></b></div><?php if((float)($p['item_discount']??0)>0): ?><div class="fco-row discount"><span>Product discounts</span><b>−<?=fcoMoney($p['item_discount'])?></b></div><?php endif; ?><?php if((float)($p['coupon_discount']??0)>0): ?><div class="fco-row discount"><span>Coupon</span><b>−<?=fcoMoney($p['coupon_discount'])?></b></div><?php endif; ?><div class="fco-row" id="deliveryRow"><span>Delivery fee</span><b>Calculated after address</b></div><div class="fco-row total"><span>Final total</span><b>Calculated at order time</b></div><div class="fco-info">Your order is placed first. Road distance, ETA and delivery fee are then calculated securely using Gemini in the background while your order page waits for the result.</div></section><button class="fco-place" type="submit">Place Fresh Food Order</button></form><?php endif; ?><?php include __DIR__.'/../Shared/fresh-food-cart-widget.php'; ?><?php include __DIR__.'/../Shared/member-notification-widget.php'; ?></div><nav class="fco-nav"><a href="<?=fcoEsc($base)?>/member"><i>⌂</i>Home</a><a href="<?=fcoEsc($base)?>/member/fresh-food"><i>🥬</i>Fresh</a><a href="<?=fcoEsc($base)?>/member/bookings"><i>▣</i>Bookings</a><a href="<?=fcoEsc($base)?>/member/profile"><i>♙</i>Profile</a></nav><script>(()=>{const d=document.querySelectorAll('input[name="order_type"]'),a=document.getElementById('addressCard'),ar=document.getElementById('address');function sync(){const delivery=document.querySelector('input[name="order_type"]:checked')?.value==='DELIVERY';document.getElementById('deliveryLabel')?.classList.toggle('active',delivery);document.getElementById('pickupLabel')?.classList.toggle('active',!delivery);a.hidden=!delivery;ar.required=delivery}d.forEach(x=>x.addEventListener('change',sync));sync();document.getElementById('locate')?.addEventListener('click',()=>{if(!navigator.geolocation){alert('Location is unavailable.');return}navigator.geolocation.getCurrentPosition(p=>{document.getElementById('lat').value=p.coords.latitude;document.getElementById('lng').value=p.coords.longitude},()=>alert('Location permission was not granted.'))})})();</script>
